          if (list.length) {
            e.preventDefault();
            toggleStar(list);
          }
          return;
        }
        case '+':
        case '=': {
          const list = ids();
          if (list.length) setImportant(list, true);
          return;
        }
        case '-': {
          const list = ids();
          if (list.length) setImportant(list, false);
          return;
        }
        case 'e': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            archive(list);
            done();
          }
          return;
        }
        case '#':
        case 'Delete': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            trash(list);
            done();
          }
          return;
        }
        case '!': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            markSpam(list);
            done();
          }
          return;
        }
        case 'I': {
          const list = ids();
          if (list.length) markRead(list, true);
          return;
        }
        case 'U': {
          const list = ids();
          if (list.length) {
            markRead(list, false);
            clearSelection();
          }
          return;
        }
        case 'b': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            openDialog({ kind: 'snooze', ids: list });
          }
          return;
        }
        case 'l':
        case 'v': {
          if (!targets().length) return void toast('Select a conversation first.', { duration: 2000 });
          e.preventDefault();
          document.querySelector<HTMLButtonElement>(key === 'l' ? '.toolbar [aria-label="Labels"]' : '.toolbar [aria-label="Move to"]')?.click();
          return;
        }
        case 'r':
        case 'a':
        case 'f': {
          if (!v.threadId) return;
          const t = getState().threads[v.threadId];
          const last = t && deliveredMessages(t).at(-1);
          if (!t || !last) return;
          e.preventDefault();
          composeReplyTo(t.id, last.id, key === 'r' ? 'reply' : key === 'a' ? 'replyAll' : 'forward');
          return;
        }
        default:
          return;
      }
    };
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('keydown', onKey);
      clearTimeout(pendingTimer);
    };
  }, []);
}

export { isUnread };

