            setUI({ cursor: rows[n].key });
          }
          return;
        }
        case 'Enter':
        case 'o': {
          if (v.threadId) return;
          const r = rows[cursorIdx];
          if (r) {
            e.preventDefault();
            const row = document.querySelector<HTMLElement>(`[data-key="${CSS.escape(r.key)}"]`);
            row?.click();
          }
          return;
        }
        case 'u':
          if (v.threadId) {
            e.preventDefault();
            navigate(v.hrefFor(undefined));
          }
          return;
        case 'x': {
          const r = rows[cursorIdx];
          if (r && !v.threadId) {
            e.preventDefault();
            toggleSelected(r.key);
          }
          return;
        }
        case 's': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            toggleStar(list);
          }
          return;
        }
        case '+':
        case '=': {
          const list = ids();
          if (list.length) setImportant(list, true);
          return;
        }
        case '-': {
          const list = ids();
          if (list.length) setImportant(list, false);
          return;
        }
        case 'e': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            archive(list);
            done();
          }
          return;
        }
        case '#':
        case 'Delete': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            trash(list);
            done();
          }
          return;
        }
        case '!': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            markSpam(list);
            done();
          }
          return;
        }
        case 'I': {
          const list = ids();
          if (list.length) markRead(list, true);
          return;
        }
        case 'U': {
          const list = ids();
          if (list.length) {
            markRead(list, false);
            clearSelection();
          }
          return;
        }
        case 'b': {
          const list = ids();
          if (list.length) {
            e.preventDefault();
            openDialog({ kind: 'snooze', ids: list });
          }
          return;
        }
        case 'l':
        case 'v': {
          if (!targets().length) return void toast('Select a conversation first.', { duration: 2000 });
          e.preventDefault();
          document.querySelector<HTMLButtonElement>(key === 'l' ? '.toolbar [aria-label="Labels"]' : '.toolbar [aria-label="Move to"]')?.click();
          return;
        }
        case 'r':
        case 'a':
        case 'f': {
          if (!v.threadId) return;
          const t = getState().threads[v.threadId];
          const last = t && deliveredMessages(t).at(-1);
          if (!t || !last) return;
          e.preventDefault();
          composeReplyTo(t.id, last.id, key === 'r' ? 'reply' : key === 'a' ? 'replyAll' : 'forward');
          return;
        }
        default:
          return;
      }
    };
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('keydown', onKey);
      clearTimeout(pendingTimer);
    };
  }, []);
}

