export function ListPane({ compactSplit }: { compactSplit?: boolean }) {
  const vm = useViewModel();
  const mail = useMail();
  const ui = useUI();
  const vp = useViewport();
  const scrollRef = useRef<HTMLDivElement>(null);
  const mobile = vp === 'mobile';
  const view = vm.view;
  const folder = view.kind === 'folder' ? view.folder : undefined;

  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = scrollMemory.get(vm.viewKey + vm.pageIndex) ?? 0;
    return () => {
      if (el) scrollMemory.set(vm.viewKey + vm.pageIndex, el.scrollTop);
    };
  }, [vm.viewKey, vm.pageIndex]);

  useEffect(() => {
    if (!ui.cursor) return;
    const el = scrollRef.current?.querySelector<HTMLElement>(`[data-key="${CSS.escape(ui.cursor)}"]`);
    el?.scrollIntoView({ block: 'nearest' });
  }, [ui.cursor]);

  const onOpen = (r: Row) => {
    setUI({ cursor: r.key });
    if (folder === 'drafts' && r.message) {
      const replyish = r.thread.messages.some((m) => !m.draft);
      openCompose({ draftId: r.message.id, threadId: r.thread.id, mode: replyish ? 'reply' : 'new' });
      return;
    }
    navigate(vm.hrefFor(r.thread.id));
  };

  const selectedSet = useMemo(() => new Set(ui.selection.keys), [ui.selection.keys]);
  const allPageSelected = vm.pageRows.length > 0 && vm.pageRows.every((r) => selectedSet.has(r.key));
  const showSelectAllBanner = !ui.selection.allInView && allPageSelected && vm.rows.length > vm.pageRows.length;
  const trashOrSpam = folder === 'trash' || folder === 'spam';
  const scopeName = view.kind === 'folder' ? (folder ? mailScope(folder) : '') : view.kind === 'label' ? vm.title : 'search results';

  return (
    <section className={`list-pane${compactSplit ? ' in-split' : ''}`} aria-label={vm.title}>
      <ListToolbar />
      <CategoryTabs />
      <div className="list-scroll" ref={scrollRef}>
        {showSelectAllBanner && (
          <div className="banner select-banner">
            All {vm.pageRows.length} conversations on this page are selected.
            <button type="button" className="link-btn" onClick={() => setSelection(vm.rows.map((r) => r.key), true)}>
              Select all {vm.rows.length} conversations in {scopeName}
            </button>
          </div>
        )}
        {ui.selection.allInView && (
          <div className="banner select-banner">
            All {vm.rows.length} conversations in {scopeName} are selected.
            <button type="button" className="link-btn" onClick={clearSelection}>
              Clear selection
            </button>
          </div>
        )}
        {trashOrSpam && vm.rows.length > 0 && (
          <div className="banner trash-banner">
            <span>
              {folder === 'trash'
                ? 'Messages that have been in Trash more than 30 days will be automatically deleted.'
                : 'Messages that have been in Spam more than 30 days will be automatically deleted.'}
            </span>
            <button
              type="button"
              className="link-btn"
              onClick={() =>
                confirmDialog(
                  {
                    title: folder === 'trash' ? 'Empty Trash?' : 'Delete all spam?',
                    body: `All ${vm.rows.length} conversations will be permanently deleted. This can’t be undone.`,
                    confirmLabel: 'Delete forever',
                    danger: true,
                  },
                  () => emptyFolder(folder as 'trash' | 'spam'),
                )
              }
            >
              {folder === 'trash' ? 'Empty Trash now' : 'Delete all spam messages now'}
            </button>
          </div>
        )}
        {vm.view.kind === 'search' && (
          <div className="search-summary">
            {vm.rows.length} result{vm.rows.length === 1 ? '' : 's'} for <strong>{vm.view.query}</strong>
          </div>
        )}
        {vm.pageRows.length === 0 ? (
          <EmptyState vm={vm} mail={mail} />
        ) : (
          <div role="listbox" aria-multiselectable="true" aria-label={vm.title} className="rows">
            {vm.pageRows.map((r) => (
              <ThreadRow
                key={r.key}
                row={r}
                selected={ui.selection.allInView || selectedSet.has(r.key)}
                cursor={ui.cursor === r.key}
                vm={vm}
                labels={mail.labels}
                settings={mail.settings}
                now={ui.now}
                mobile={mobile}
                onOpen={onOpen}
              />
            ))}
          </div>
        )}
        {vm.pageRows.length > 0 && (
          <div className="list-foot">
            {vm.rows.length} conversation{vm.rows.length === 1 ? '' : 's'} · Local mailbox, stored in this browser
          </div>
        )}
      </div>
    </section>
  );
}

function mailScope(folder: string): string {
  const names: Record<string, string> = { inbox: 'Inbox', starred: 'Starred', snoozed: 'Snoozed', important: 'Important', sent: 'Sent', drafts: 'Drafts', scheduled: 'Scheduled', all: 'All Mail', spam: 'Spam', trash: 'Trash' };
  return names[folder] ?? folder;
}

import { forwardRef, type ButtonHTMLAttributes, type CSSProperties, type MouseEvent, type ReactNode } from 'react';
import type { Label } from '../lib/types';
import { avatarColor, initialOf } from '../lib/mail';

export function Icon({ name, fill, size, className = '', style }: { name: string; fill?: boolean; size?: 'sm' | 'xs'; className?: string; style?: CSSProperties }) {
  return (
    <span className={`icon${fill ? ' fill' : ''}${size ? ` ${size}` : ''}${className ? ` ${className}` : ''}`} style={style} aria-hidden="true">
      {name}
    </span>
  );
}

interface IconButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  icon: string;
  label: string;
  fill?: boolean;
  small?: boolean;
  active?: boolean;
  tip?: boolean;
  badge?: ReactNode;
}

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { icon, label, fill, small, active, tip = true, badge, className = '', ...rest },
  ref,
) {
  return (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      data-tip={tip ? label : undefined}
      className={`icon-btn${small ? ' sm' : ''}${active ? ' active' : ''}${className ? ` ${className}` : ''}`}
      {...rest}
    >
      <Icon name={icon} fill={fill} />
      {badge}
    </button>
  );
});

export function Avatar({ name, email, color, size = 40 }: { name: string; email?: string; color?: string; size?: number }) {
  const label = name || email || '?';
  return (
    <span
      className="avatar"
      aria-hidden="true"
      style={{ width: size, height: size, fontSize: Math.round(size * 0.44), background: avatarColor(label, color) }}
    >
      {initialOf(label)}
    </span>
  );
}

export function Checkbox({
  state,
  label,
  onChange,
  className = '',
}: {
  state: 'checked' | 'unchecked' | 'indeterminate';
  label: string;
  onChange: (e: MouseEvent) => void;
  className?: string;
}) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={state === 'indeterminate' ? 'mixed' : state === 'checked'}
      aria-label={label}
      className={`cb-hit ${className}`}
      onClick={(e) => {
        e.stopPropagation();
        onChange(e);
      }}
    >
      <span className={`cb ${state === 'checked' ? 'checked' : state === 'indeterminate' ? 'indeterminate' : ''}`} />
    </button>
  );
}

export function LabelChip({ label, onRemove }: { label: Label; onRemove?: () => void }) {
  return (
    <span className="chip" style={{ ['--chip' as string]: label.color }}>
      {label.name}
      {onRemove && (
        <button type="button" aria-label={`Remove label ${label.name}`} onClick={onRemove}>
          <Icon name="close" size="xs" />
        </button>
      )}
    </span>
  );
}

/** Wrap occurrences of any `terms` in <mark>. */
export function Highlight({ text, terms }: { text: string; terms: string[] }) {
  if (!terms.length || !text) return <>{text}</>;
  const lower = text.toLowerCase();
  const ranges: [number, number][] = [];
  for (const t of terms) {
    if (!t) continue;
    let i = lower.indexOf(t);
    while (i >= 0) {
      ranges.push([i, i + t.length]);
      i = lower.indexOf(t, i + t.length);
    }
  }
  if (!ranges.length) return <>{text}</>;
  ranges.sort((a, b) => a[0] - b[0]);
  const merged: [number, number][] = [];
  for (const r of ranges) {
    const last = merged[merged.length - 1];
    if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]);
    else merged.push([...r]);
  }
  const out: ReactNode[] = [];
  let pos = 0;
  merged.forEach(([s, e], i) => {
    if (s > pos) out.push(text.slice(pos, s));
    out.push(<mark key={i}>{text.slice(s, e)}</mark>);
    pos = e;
  });
  if (pos < text.length) out.push(text.slice(pos));
  return <>{out}</>;
}

}

/* icons */
.icon {
  font-family: 'Material Symbols Outlined';
  font-weight: 400;
  font-style: normal;
  font-size: 24px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'liga';
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  user-select: none;
  flex-shrink: 0;
  overflow: hidden;
  width: 1em;
  height: 1em;
}
.icon.fill {
  font-variation-settings: 'FILL' 1, 'wght' 400, 'GRAD' 0, 'opsz' 24;
}
.icon.sm {
  font-size: 18px;
}
.icon.xs {
  font-size: 16px;
}

/* buttons */
.icon-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  color: var(--text-2);
  transition: background 0.12s;
  flex-shrink: 0;
}
.icon-btn:hover:not(:disabled) {
  background: var(--hover);
}
.icon-btn:active:not(:disabled) {
  background: var(--hover-strong);
}
.icon-btn:disabled {
  opacity: 0.38;
  cursor: default;
}
.icon-btn.sm {
  width: 32px;
  height: 32px;
}
.icon-btn.sm .icon {
  font-size: 20px;
}
.icon-btn.active {
  background: var(--accent-container);
  color: var(--on-accent-container);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 24px;
  border-radius: 20px;
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.01em;
  transition: background 0.12s, box-shadow 0.12s;
  white-space: nowrap;
}
.btn.primary {
  background: var(--accent);
  color: var(--on-accent);
}
.btn.primary:hover:not(:disabled) {
  background: var(--accent-hover);
  box-shadow: var(--shadow-1);
}
.btn.text {
  color: var(--accent);
  padding: 0 12px;
}
.btn.text:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
.btn.outline {
  border: 1px solid var(--line-strong);
  color: var(--text-2);
  padding: 0 20px;
}
.btn.outline:hover:not(:disabled) {
  background: var(--hover);
}
.btn.danger {
