}

/* checkbox */
.cb {
  position: relative;
  display: inline-block;
  width: 18px;
  height: 18px;
  border: 2px solid var(--text-3);
  border-radius: 2px;
  flex-shrink: 0;
  transition: background 0.1s, border-color 0.1s;
  background: transparent;
}
.cb.checked,
.cb.indeterminate {
  background: var(--accent);
  border-color: var(--accent);
}
.cb.checked::after {
  content: '';
  position: absolute;
  left: 4px;
  top: 0.5px;
  width: 4px;
  height: 9px;
  border: solid var(--on-accent);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.cb.indeterminate::after {
  content: '';
  position: absolute;
  left: 2px;
  top: 6px;
  width: 10px;
  height: 2px;
  background: var(--on-accent);
}
.cb-hit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
}
.cb-hit:hover {
  background: var(--hover);
}

/* avatar */
