  border-right: 1px solid var(--line);
}
.split-thread {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.split-thread > * {
  flex: 1;
  min-height: 0;
}
.list-pane.in-split .row {
  display: grid;
  grid-template-columns: 32px 32px 1fr auto;
  grid-template-areas:
    'chk star sender date'
    'chk star main att';
  height: auto;
  min-height: 56px;
  padding: 6px 12px 6px 4px;
  align-items: center;
  row-gap: 0;
}
