:root[data-theme='dark'] .draft-tag {
  color: #f28b82;
}
.row-count {
  font-size: 12px;
  color: var(--text-3);
  font-weight: 400;
  flex-shrink: 0;
}
.row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  white-space: nowrap;
}
.row-subject {
  flex-shrink: 0;
  max-width: 60%;
