  font-weight: 400;
}
.row-dash {
  white-space: pre;
}
.row-att {
  color: var(--text-3);
  margin: 0 8px;
}
.row-date {
  flex: 0 0 auto;
  min-width: 56px;
  text-align: right;
  font-size: 12px;
  color: var(--text-3);
