.list-pane.in-split .row-subject {
  max-width: 100%;
}
.list-pane.in-split .row-snippet {
  display: none;
}
.list-pane.in-split .cat-tab {
  min-width: 0;
  flex: 1 1 0;
  padding: 10px 6px 8px;
}
.list-pane.in-split .cat-names,
.list-pane.in-split .cat-badge {
  display: none;
}
.list-pane.in-split .cat-top {
  gap: 6px;
}
.list-pane.in-split .cat-name {
  font-size: 13px;
}

.list-foot {
  padding: 24px 16px 32px;
  text-align: center;
  font-size: 12px;
  color: var(--text-4);
}

/* ---------- empty state ---------- */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 72px 24px;
  gap: 8px;
  color: var(--text-3);
}
.empty-icon {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--surface-read);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  margin-bottom: 8px;
}
.empty-icon .icon {
  font-size: 48px;
}
.empty-state h2 {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
  color: var(--text);
}
.empty-state p {
  margin: 0;
  max-width: 420px;
  line-height: 1.5;
}
.empty-hint {
  font-size: 13px;
  color: var(--text-4);
}
.empty-state .btn {
  margin-top: 12px;
}

