.snooze-menu {
  min-width: 240px;
}
.label-picker,
.move-picker {
  width: 260px;
  padding: 8px 0 0;
  display: flex;
  flex-direction: column;
  max-height: min(420px, 70vh);
}
.picker-title {
  padding: 4px 16px 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-3);
}
.picker-search {
  padding: 0 12px 8px;
}
.picker-input {
