  padding: 0 8px;
  background: transparent;
  outline: none;
}
.picker-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}
.picker-list {
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}
.picker-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 4px 16px;
  min-height: 32px;
  text-align: left;
  color: var(--text);
}
.picker-row:hover,
.picker-row.focus {
  background: var(--hover);
}
.picker-name {
