  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.picker-empty {
  padding: 12px 16px;
  color: var(--text-3);
  font-size: 13px;
}
.picker-foot {
  border-top: 1px solid var(--line);
  padding: 4px 0;
}
.picker-apply {
  border-top: 1px solid var(--line);
  padding: 8px 12px;
  display: flex;
  justify-content: flex-end;
}
.picker-apply .btn {
  height: 32px;
}
.menu-label-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

