}
.thread-pane.placeholder .empty-state {
  flex: 1;
}
.thread-toolbar {
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.thread-toolbar::-webkit-scrollbar {
  display: none;
}
.thread-scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
  overscroll-behavior: contain;
}
.thread-inner {
  max-width: 1040px;
  padding: 4px 24px 48px 24px;
  margin: 0 auto;
}
.thread-pane.embedded .thread-inner {
  max-width: none;
  padding: 4px 16px 40px 20px;
}

.thread-head {
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 4px 12px;
  padding: 8px 0 16px 52px;
}
.thread-subject {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 22px;
  line-height: 32px;
  font-weight: 400;
  color: var(--text);
  overflow-wrap: anywhere;
}
.thread-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  min-height: 32px;
}
.thread-chips .chip {
  height: 22px;
  line-height: 22px;
}
.thread-chips .chip button {
  margin-left: 2px;
}
.thread-head-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 0;
}
.icon-btn.imp-on {
  color: var(--important);
}
.icon-btn.star-on {
  color: var(--star);
}

.state-banner,
.sched-banner {
  justify-content: flex-start;
  border-radius: 8px;
  margin: 0 0 12px 52px;
  background: var(--surface-read);
  color: var(--text-2);
  border: 1px solid var(--line);
  text-align: left;
}
.state-banner .icon,
.sched-banner .icon {
  color: var(--text-3);
}
.state-banner.warn {
