  color: var(--danger);
  border-color: transparent;
}
.state-banner.warn .icon {
  color: var(--danger);
}
.state-banner .link-btn,
.sched-banner .link-btn {
  color: var(--accent);
  text-decoration: none;
  margin-left: auto;
}
.state-banner.warn .link-btn {
  color: var(--danger);
  text-decoration: underline;
}
.sched-banner {
  margin: 0 0 16px 0;
  background: var(--accent-container);
  color: var(--on-accent-container);
  border-color: transparent;
}
.sched-banner .icon {
  color: inherit;
}

/* ---------- messages ---------- */
