}
.msg-c-snippet {
  flex: 1;
  min-width: 0;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--font-text);
}
.msg-c-date {
  font-size: 12px;
  color: var(--text-3);
  white-space: nowrap;
  padding-right: 8px;
}
.msg.collapsed .row-att {
  color: var(--text-3);
  margin: 0;
}
.msg.draft {
  border-left: 3px solid #d93025;
  padding-left: 12px;
}

.msg.expanded {
  padding: 16px 0 8px;
}
.msg-head {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
