.msg-body {
  margin: 12px 0 0 52px;
  font-family: var(--font-text);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  overflow-wrap: anywhere;
  min-width: 0;
}
.msg-html > :first-child {
