}

/* ---------- footer ---------- */
.compose-foot {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px 10px 16px;
  flex-shrink: 0;
}
.send-split {
  display: inline-flex;
  align-items: stretch;
  height: 40px;
  border-radius: 20px;
  background: var(--accent);
  color: var(--on-accent);
  margin-right: 8px;
}
.send-split:hover {
  box-shadow: var(--shadow-1);
}
.send-btn {
  padding: 0 20px 0 24px;
  border-radius: 20px 0 0 20px;
  font-family: var(--font-ui);
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.01em;
  color: inherit;
}
.send-btn:hover {
  background: var(--accent-hover);
}
.send-caret {
  width: 32px;
