  align-items: center;
  justify-content: center;
  color: inherit;
}
.send-caret:hover {
  background: var(--accent-hover);
}
.send-caret .icon {
  font-size: 22px;
}
.foot-tools {
  display: flex;
  align-items: center;
}
.saved-note {
  font-size: 12px;
  color: var(--text-4);
  margin-right: 4px;
}

/* ---------- inline reply ---------- */
.inline-composer {
  margin: 20px 0 0 52px;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  background: var(--surface);
  box-shadow: var(--shadow-1);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.inline-composer:focus-within {
  box-shadow: var(--shadow-2);
}
.ic-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 8px 8px 0 16px;
  color: var(--text-3);
  min-height: 44px;
}
.ic-head > .icon {
  margin-top: 10px;
