/* ---------- mobile full-screen compose ---------- */
.compose-dock.mobile {
  inset: 0;
  right: 0;
  max-width: none;
  align-items: stretch;
  gap: 0;
}
.compose-dock.mobile .compose-win,
.compose-dock.mobile .compose-win.minimized {
  width: 100%;
  max-width: none;
  height: 100%;
  max-height: none;
  border-radius: 0;
  box-shadow: none;
  padding-top: env(safe-area-inset-top);
}
.compose-dock.mobile .compose-body {
  min-height: 0;
}

