}
.settings-tab:hover {
  background: var(--hover);
}
.settings-tab.active {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 700;
}
.settings-content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: 16px 40px 64px 32px;
  max-width: 880px;
}
.settings-section-title {
  margin: 8px 0 8px;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
}
.set-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.set-text {
  min-width: 0;
  flex: 1;
}
.set-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  display: block;
}
.set-desc {
  font-size: 13px;
  color: var(--text-3);
  margin-top: 2px;
  line-height: 1.4;
}
.set-control {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.set-inline {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--text-3);
}
.set-group-title {
  margin: 28px 0 4px;
