  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.set-head-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}
.set-lead {
  margin: 0;
  color: var(--text-3);
  line-height: 1.5;
  max-width: 520px;
}

.toggle {
  position: relative;
  display: inline-flex;
  cursor: pointer;
  flex-shrink: 0;
}
.toggle input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}
.toggle-track {
  width: 44px;
  height: 24px;
  border-radius: 12px;
  background: var(--line-strong);
  position: relative;
  transition: background 0.15s;
  pointer-events: none;
}
.toggle-thumb {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s, width 0.15s, height 0.15s, top 0.15s, left 0.15s;
}
.toggle input:checked + .toggle-track {
  background: var(--accent);
}
.toggle input:checked + .toggle-track .toggle-thumb {
  transform: translateX(20px);
  background: var(--on-accent);
}
:root[data-theme='dark'] .toggle input:checked + .toggle-track .toggle-thumb {
  background: var(--on-accent);
}
.toggle input:focus-visible + .toggle-track {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.toggle input:disabled {
  cursor: default;
}
.toggle input:disabled + .toggle-track {
  opacity: 0.5;
}

.option-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 0 4px;
}
.option-card {
  width: 148px;
  padding: 16px 12px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
  color: var(--text-2);
  transition: background 0.12s, border-color 0.12s;
}
.option-card .icon {
  font-size: 32px;
}
.option-card:hover {
  background: var(--hover);
}
.option-card.on {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
  background: var(--accent-container);
  color: var(--on-accent-container);
}
.oc-title {
  font-weight: 500;
  font-family: var(--font-ui);
  font-size: 14px;
}
.oc-sub {
  font-size: 12px;
  opacity: 0.8;
}
.select {
  height: 36px;
  min-width: 160px;
  padding: 0 8px;
}
.textarea {
  width: 100%;
  min-height: 110px;
  padding: 10px 12px;
  resize: vertical;
  font-family: var(--font-text);
  line-height: 1.5;
}
.sig-editor {
  padding: 16px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sig-preview {
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
  padding: 12px 16px;
  margin-top: 8px;
  background: var(--surface-read);
}
.sig-preview-title {
  font-size: 12px;
  color: var(--text-3);
  margin-bottom: 8px;
}
.sig-preview-body {
  font-family: var(--font-text);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-2);
  white-space: pre-wrap;
}
.label-table {
  border-top: 1px solid var(--line);
  margin-top: 8px;
}
.label-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  border-bottom: 1px solid var(--line);
  padding: 4px 0;
}
.label-name {
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}
.label-name:hover {
  text-decoration: underline;
}
.label-count {
  color: var(--text-3);
  font-size: 13px;
}
.stat-line {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  padding: 12px 0;
  color: var(--text-3);
  font-size: 13px;
}
.btn.danger-text {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 40%, transparent);
}

/* ---------- dialogs ---------- */
.dialog.wide {
  width: min(720px, 94vw);
}
.field-error {
  color: var(--danger);
  font-size: 12px;
  margin-top: 4px;
  display: block;
}
.label-preview {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-3);
  font-size: 13px;
  margin: 4px 0 8px;
}
.dt-note {
  color: var(--text-3);
  font-size: 13px;
  margin: 4px 0 0 !important;
  min-height: 20px;
}
.shortcut-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px 32px;
  max-height: min(60vh, 520px);
  overflow-y: auto;
  padding: 4px 4px 4px 0;
}
.shortcut-grid h3 {
  margin: 12px 0 4px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 30px;
  font-size: 13px;
  border-bottom: 1px solid var(--line);
}
.kbd-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.kbd-sep {
  font-size: 11px;
  color: var(--text-3);
}
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--surface-read);
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--text-2);
}

/* attachment preview */
.preview-scrim {
  position: fixed;
  inset: 0;
  z-index: 1300;
  background: rgba(15, 17, 20, 0.92);
  display: flex;
  flex-direction: column;
  color: #fff;
}
.preview-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 64px;
  padding: 0 12px;
  flex-shrink: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.55), transparent);
}
.preview-title {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
  font-family: var(--font-ui);
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.preview-size {
  font-size: 12px;
  font-weight: 400;
  opacity: 0.7;
}
.preview-count {
  font-size: 13px;
  opacity: 0.8;
  margin-right: 8px;
}
.preview-stage {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: 0 72px 32px;
}
.preview-img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  border-radius: 6px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
  background: #fff;
}
.preview-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}
.preview-nav.left {
  left: 16px;
}
.preview-nav.right {
  right: 16px;
}
.icon-btn.on-dark {
  color: #fff;
}
.icon-btn.on-dark:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.16);
}
.preview-doc {
  height: 100%;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.doc-page {
  width: min(560px, 100%);
  max-height: 100%;
  background: #fff;
  color: #202124;
  border-radius: 6px;
  padding: 40px 44px 32px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
  overflow: auto;
  position: relative;
}
.doc-kind {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 4px;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}
.doc-title {
  font-family: var(--font-ui);
  font-size: 22px;
  margin-bottom: 20px;
  overflow-wrap: anywhere;
}
.doc-lines {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.doc-lines span {
  height: 8px;
  border-radius: 4px;
  background: #e8eaed;
  display: block;
}
.doc-note {
  margin-top: 24px;
  font-size: 12px;
  color: #5f6368;
}

