/* ---------- settings ---------- */
.settings {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--surface);
}
.settings-head {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 56px;
  padding: 0 8px 0 8px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--line);
}
.settings-head h2 {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
}
.settings-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.settings-nav {
  width: 220px;
  flex-shrink: 0;
  padding: 12px 0;
  border-right: 1px solid var(--line);
  overflow-y: auto;
}
.settings-tab {
  display: flex;
  align-items: center;
  height: 40px;
  padding: 0 24px;
  color: var(--text-2);
  text-decoration: none;
  font-family: var(--font-ui);
  font-size: 14px;
  border-radius: 0 20px 20px 0;
  margin-right: 12px;
}
.settings-tab:hover {
  background: var(--hover);
}
.settings-tab.active {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 700;
}
.settings-content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: 16px 40px 64px 32px;
  max-width: 880px;
}
.settings-section-title {
  margin: 8px 0 8px;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
}
.set-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.set-text {
  min-width: 0;
  flex: 1;
}
.set-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  display: block;
}
.set-desc {
  font-size: 13px;
  color: var(--text-3);
  margin-top: 2px;
  line-height: 1.4;
}
.set-control {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.set-inline {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--text-3);
}
.set-group-title {
  margin: 28px 0 4px;
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.set-head-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}
.set-lead {
  margin: 0;
  color: var(--text-3);
  line-height: 1.5;
  max-width: 520px;
}

.toggle {
  position: relative;
  display: inline-flex;
  cursor: pointer;
  flex-shrink: 0;
}
.toggle input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}
.toggle-track {
  width: 44px;
  height: 24px;
  border-radius: 12px;
  background: var(--line-strong);
  position: relative;
  transition: background 0.15s;
  pointer-events: none;
}
.toggle-thumb {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s, width 0.15s, height 0.15s, top 0.15s, left 0.15s;
}
.toggle input:checked + .toggle-track {
  background: var(--accent);
}
.toggle input:checked + .toggle-track .toggle-thumb {
  transform: translateX(20px);
  background: var(--on-accent);
}
:root[data-theme='dark'] .toggle input:checked + .toggle-track .toggle-thumb {
  background: var(--on-accent);
}
.toggle input:focus-visible + .toggle-track {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.toggle input:disabled {
  cursor: default;
}
.toggle input:disabled + .toggle-track {
  opacity: 0.5;
}

.option-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 0 4px;
}
.option-card {
  width: 148px;
  padding: 16px 12px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
  color: var(--text-2);
  transition: background 0.12s, border-color 0.12s;
}
.option-card .icon {
  font-size: 32px;
}
.option-card:hover {
  background: var(--hover);
}
.option-card.on {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
  background: var(--accent-container);
  color: var(--on-accent-container);
}
.oc-title {
  font-weight: 500;
  font-family: var(--font-ui);
  font-size: 14px;
}
.oc-sub {
  font-size: 12px;
  opacity: 0.8;
}
.select {
  height: 36px;
  min-width: 160px;
  padding: 0 8px;
}
.textarea {
  width: 100%;
  min-height: 110px;
  padding: 10px 12px;
  resize: vertical;
  font-family: var(--font-text);
  line-height: 1.5;
}
.sig-editor {
  padding: 16px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sig-preview {
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
  padding: 12px 16px;
  margin-top: 8px;
  background: var(--surface-read);
}
.sig-preview-title {
  font-size: 12px;
  color: var(--text-3);
  margin-bottom: 8px;
}
.sig-preview-body {
  font-family: var(--font-text);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-2);
  white-space: pre-wrap;
}
.label-table {
  border-top: 1px solid var(--line);
  margin-top: 8px;
}
.label-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  border-bottom: 1px solid var(--line);
  padding: 4px 0;
}
.label-name {
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}
.label-name:hover {
  text-decoration: underline;
}
.label-count {
  color: var(--text-3);
  font-size: 13px;
}
.stat-line {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  padding: 12px 0;
  color: var(--text-3);
  font-size: 13px;
}
.btn.danger-text {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 40%, transparent);
}

/* ---------- dialogs ---------- */
.dialog.wide {
  width: min(720px, 94vw);
}
.field-error {
  color: var(--danger);
  font-size: 12px;
  margin-top: 4px;
  display: block;
}
.label-preview {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-3);
  font-size: 13px;
  margin: 4px 0 8px;
}
.dt-note {
  color: var(--text-3);
  font-size: 13px;
  margin: 4px 0 0 !important;
  min-height: 20px;
}
.shortcut-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px 32px;
  max-height: min(60vh, 520px);
  overflow-y: auto;
  padding: 4px 4px 4px 0;
}
.shortcut-grid h3 {
  margin: 12px 0 4px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 30px;
  font-size: 13px;
  border-bottom: 1px solid var(--line);
}
.kbd-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.kbd-sep {
  font-size: 11px;
  color: var(--text-3);
}
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--surface-read);
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--text-2);
}

/* attachment preview */
.preview-scrim {
  position: fixed;
  inset: 0;
  z-index: 1300;
  background: rgba(15, 17, 20, 0.92);
  display: flex;
  flex-direction: column;
  color: #fff;
}
.preview-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 64px;
  padding: 0 12px;
  flex-shrink: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.55), transparent);
}
.preview-title {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
  font-family: var(--font-ui);
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.preview-size {
  font-size: 12px;
  font-weight: 400;
  opacity: 0.7;
}
.preview-count {
  font-size: 13px;
  opacity: 0.8;
  margin-right: 8px;
}
.preview-stage {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: 0 72px 32px;
}
.preview-img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  border-radius: 6px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
  background: #fff;
}
.preview-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}
.preview-nav.left {
  left: 16px;
}
.preview-nav.right {
  right: 16px;
}
.icon-btn.on-dark {
  color: #fff;
}
.icon-btn.on-dark:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.16);
}
.preview-doc {
  height: 100%;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.doc-page {
  width: min(560px, 100%);
  max-height: 100%;
  background: #fff;
  color: #202124;
  border-radius: 6px;
  padding: 40px 44px 32px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
  overflow: auto;
  position: relative;
}
.doc-kind {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 4px;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}
.doc-title {
  font-family: var(--font-ui);
  font-size: 22px;
  margin-bottom: 20px;
  overflow-wrap: anywhere;
}
.doc-lines {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.doc-lines span {
  height: 8px;
  border-radius: 4px;
  background: #e8eaed;
  display: block;
}
.doc-note {
  margin-top: 24px;
  font-size: 12px;
  color: #5f6368;
}

args.streamContent:
/* ---------- tablet (< 1100) ---------- */
.app:not([data-vp='desktop']) .header-left {
  width: auto;
}
.app:not([data-vp='desktop']) .main {
  margin: 0 8px 8px 8px;
}
.app[data-vp='tablet'] .row-sender {
  flex-basis: 160px;
  width: 160px;
}
.app[data-vp='tablet'] .header-search {
  max-width: none;
}

/* ---------- touch: no hover chrome ---------- */
@media (hover: none) {
  .row:hover {
    box-shadow: none;
  }
  .row:hover .row-actions {
    display: none;
  }
  .row:hover .row-date,
  .row:hover .row-att {
    visibility: visible;
  }
  .nav-row:hover .nav-count {
    visibility: visible;
  }
  .nav-more-btn {
    opacity: 1;
  }
}

/* ---------- mobile (< 760) ---------- */
.app[data-vp='mobile'] .header {
  height: 56px;
  padding: 0 4px;
  gap: 0;
}
.app[data-vp='mobile'] .header.searching {
  padding: 4px 8px;
}
.app[data-vp='mobile'] .header-left {
  flex: 1;
  min-width: 0;
}
.app[data-vp='mobile'] .wordmark {
  font-size: 18px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.app[data-vp='mobile'] .brand {
  min-width: 0;
  padding-right: 4px;
}
.app[data-vp='mobile'] .header-right {
  gap: 0;
}
.app[data-vp='mobile'] .account-btn {
  margin: 0 4px 0 0;
}
.app[data-vp='mobile'] .main {
  margin: 0;
  border-radius: 0;
}
.app[data-vp='mobile'][data-thread='true'] .header {
  display: none;
}
.app[data-vp='mobile'] .toolbar {
  height: 52px;
  padding: 0 4px;
}
.app[data-vp='mobile'] .toolbar.selection-mode {
  background: var(--accent-container);
  color: var(--on-accent-container);
}
.app[data-vp='mobile'] .toolbar.selection-mode .icon-btn {
  color: inherit;
}
.app[data-vp='mobile'] .cat-tab {
  flex: 0 0 auto;
  min-width: 0;
  padding: 10px 14px 8px;
}
.app[data-vp='mobile'] .cat-names {
  display: none;
}
.app[data-vp='mobile'] .cat-tabs {
  padding-left: 0;
}

.app[data-vp='mobile'] .row.mrow {
  height: auto;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 8px 10px 12px;
  border-bottom: 1px solid var(--line);
}
.mrow-avatar {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: inline-flex;
  margin-top: 2px;
}
.sel-avatar {
  width: 40px;
  height: 40px;
  background: var(--accent);
  color: var(--on-accent);
}
.mrow-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.mrow-line1,
.mrow-line2,
.mrow-line3 {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.mrow-line1 {
  justify-content: space-between;
}
.mrow-sender {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 15px;
}
.row.unread .mrow-sender {
  font-weight: 700;
}
.mrow-date {
  flex-shrink: 0;
  font-size: 12px;
  color: var(--text-3);
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.row.unread .mrow-date {
  font-weight: 700;
  color: var(--accent);
}
.mrow-subject {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 14px;
  color: var(--text);
}
.row.unread .mrow-subject {
  font-weight: 500;
}
.mrow-line2 .row-att {
  margin: 0;
}
.mrow-line3 {
  font-size: 13px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
}
.mrow-line3 > :first-child:not(.mrow-chips) {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mrow-chips {
  display: inline-flex;
  gap: 4px;
  margin-left: auto;
  flex-shrink: 0;
}
.mrow-star {
  margin-top: 22px;
  width: 36px;
  height: 36px;
}
.mrow .row-count {
  color: var(--text-3);
}

/* thread */
.app[data-vp='mobile'] .thread-inner {
  padding: 0 12px 40px;
}
.app[data-vp='mobile'] .thread-head {
  padding-left: 0;
  padding-top: 4px;
}
.app[data-vp='mobile'] .thread-subject {
  font-size: 20px;
  line-height: 28px;
}
.app[data-vp='mobile'] .thread-head-actions {
  margin-left: 0;
  width: 100%;
}
.app[data-vp='mobile'] .msg-body,
.app[data-vp='mobile'] .att-section,
.app[data-vp='mobile'] .reply-area,
.app[data-vp='mobile'] .inline-composer,
.app[data-vp='mobile'] .state-banner {
  margin-left: 0;
}
.app[data-vp='mobile'] .msg-c-name {
  flex-basis: 96px;
  width: 96px;
}
.app[data-vp='mobile'] .msg-head {
  flex-wrap: wrap;
}
.app[data-vp='mobile'] .msg-addr {
  display: none;
}
.app[data-vp='mobile'] .msg-date {
  display: none;
}
.app[data-vp='mobile'] .unsub {
  order: 3;
  margin-left: 52px;
  margin-top: 0;
}
.app[data-vp='mobile'] .att-grid {
  grid-template-columns: 1fr;
}
.app[data-vp='mobile'] .reply-bar .btn {
  flex: 1;
  padding: 0 12px;
  min-width: 0;
}
.app[data-vp='mobile'] .inline-composer {
  border-radius: 12px;
}
.app[data-vp='mobile'] .older-bar {
  margin-left: 0;
}
.app[data-vp='mobile'] .compose-head.mobile + .compose-fields,
.app[data-vp='mobile'] .compose-win .compose-fields {
  padding: 0 16px;
}

/* settings */
.app[data-vp='mobile'] .settings-body {
  flex-direction: column;
}
.app[data-vp='mobile'] .settings-nav {
  width: auto;
  display: flex;
  overflow-x: auto;
  border-right: 0;
  border-bottom: 1px solid var(--line);
  padding: 4px 8px;
  scrollbar-width: none;
}
.app[data-vp='mobile'] .settings-tab {
  flex-shrink: 0;
  border-radius: 20px;
  margin: 0 2px;
  height: 36px;
  padding: 0 16px;
}
.app[data-vp='mobile'] .settings-content {
  padding: 8px 16px 48px;
}
.app[data-vp='mobile'] .set-row {
  flex-wrap: wrap;
  gap: 8px;
}
.app[data-vp='mobile'] .option-card {
  flex: 1 1 calc(50% - 6px);
  width: auto;
}
.app[data-vp='mobile'] .set-head-row {
  flex-direction: column;
  align-items: flex-start;
}

/* dialogs and popovers */
.app[data-vp='mobile'] .shortcut-grid {
  grid-template-columns: 1fr;
}
.app[data-vp='mobile'] .quick-settings,
.app[data-vp='mobile'] .account-menu {
  width: min(340px, 94vw);
}
.app[data-vp='mobile'] .preview-stage {
  padding: 0 8px 24px;
}
.app[data-vp='mobile'] .doc-page {
  padding: 28px 24px;
}
.app[data-vp='mobile'] .toasts {
  bottom: 88px;
}
.app[data-vp='mobile'] .banner {
  text-align: left;
  justify-content: flex-start;
}

@media (max-width: 400px) {
  .app[data-vp='mobile'] .header-right [aria-label='Quick settings'] {
    display: none;
  }
