const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", e => errors.push("pageerror: " + String(e).slice(0, 400)));
const st = () => page.evaluate(() => { const s = JSON.parse(localStorage.getItem("mail.state.v1") || "{}"); const t = s.threads && s.threads["t_p1"]; return t ? { starred: t.starred, inbox: t.inbox, trashed: t.trashed, important: t.important, labels: t.labelIds } : null; });
const out = {};
// star from thread view
await page.click('.thread-head-actions [aria-label="Add star"]');
await page.waitForTimeout(500);
out.afterStar = await st();
