await page.waitForTimeout(700);
out.afterArchive = { hash: await page.evaluate(() => location.hash), st: await st(), toast: await page.textContent(".toast").catch(() => null) };
await saveScreenshot(await page.screenshot(), "d-toast.png");
// undo
await page.click(".toast-action");
await page.waitForTimeout(600);
out.afterUndo = await st();
// list keyboard: j j x  -> selection
