await page.waitForTimeout(300);
out.sel = await page.evaluate(() => ({ selected: document.querySelectorAll(".row.selected").length, cursor: document.querySelectorAll(".row.cursor").length, tb: [...document.querySelectorAll(".toolbar [aria-label]")].map(b => b.getAttribute("aria-label")).slice(0, 14), count: document.querySelector(".sel-count-inline")?.textContent }));
await saveScreenshot(await page.screenshot(), "d-selected.png");
await page.keyboard.press("Escape");
