const T = (id) => page.evaluate((id) => { const t = JSON.parse(localStorage.getItem("mail.state.v1")).threads[id]; return t && { inbox: t.inbox, trashed: t.trashed, snoozedUntil: !!t.snoozedUntil, labels: t.labelIds, spam: t.spam }; }, id);
// find Tom Becker thread
const key = await page.evaluate(() => document.querySelector(".row")?.dataset.key);
out.firstKey = key;
await page.click(".row >> nth=0");
await page.waitForTimeout(500);
const id = await page.evaluate(() => location.hash.split("/")[2].split("?")[0]);
out.id = id;
// label picker
await page.click('.thread-toolbar [aria-label="Labels"]');
await page.waitForTimeout(300);
out.picker = await page.evaluate(() => [...document.querySelectorAll(".label-picker .picker-row")].map(r => r.textContent.trim()).slice(0, 8));
await saveScreenshot(await page.screenshot(), "d-labelpicker.png");
await page.click('.label-picker .picker-row:has-text("Finance")');
await page.click(".picker-apply .btn");
await page.waitForTimeout(400);
out.labeled = await T(id);
// snooze
await page.click('.thread-toolbar [aria-label="Snooze"]');
await page.waitForTimeout(300);
out.snoozeItems = await page.evaluate(() => [...document.querySelectorAll(".popover .menu-item")].map(r => r.textContent.trim()));
await page.click('.popover .menu-item >> nth=0');
await page.waitForTimeout(600);
out.snoozed = { hash: await page.evaluate(() => location.hash), t: await T(id), toast: await page.textContent(".toast") };
await page.goto("http://127.0.0.1:9232/#/snoozed");
await page.waitForTimeout(500);
out.snoozedView = await page.evaluate(() => [...document.querySelectorAll(".row")].map(r => r.querySelector(".row-subject").textContent + " @ " + r.querySelector(".row-date").textContent));
// trash
await page.click(".row >> nth=0");
await page.waitForTimeout(400);
await page.click('.thread-toolbar [aria-label="Delete"]');
await page.waitForTimeout(500);
out.trashed = await T(id);
await page.goto("http://127.0.0.1:9232/#/trash");
await page.waitForTimeout(500);
out.trashView = await page.evaluate(() => ({ rows: document.querySelectorAll(".row").length, banner: document.querySelector(".trash-banner")?.textContent }));
console.log(JSON.stringify({ out, errors }, null, 1));
EOF

