success.beforeFullFileContent:
/* ---------- settings ---------- */
.settings {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--surface);
}
.settings-head {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 56px;
  padding: 0 8px 0 8px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--line);
}
.settings-head h2 {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
}
.settings-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.settings-nav {
  width: 220px;
  flex-shrink: 0;
  padding: 12px 0;
  border-right: 1px solid var(--line);
  overflow-y: auto;
}
.settings-tab {
  display: flex;
  align-items: center;
  height: 40px;
  padding: 0 24px;
  color: var(--text-2);
  text-decoration: none;
  font-family: var(--font-ui);
  font-size: 14px;
  border-radius: 0 20px 20px 0;
  margin-right: 12px;
}
.settings-tab:hover {
  background: var(--hover);
}
.settings-tab.active {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 700;
}
.settings-content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: 16px 40px 64px 32px;
  max-width: 880px;
}
.settings-section-title {
  margin: 8px 0 8px;
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
}
.set-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.set-text {
  min-width: 0;
  flex: 1;
}
.set-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  display: block;
}
.set-desc {
  font-size: 13px;
  color: var(--text-3);
  margin-top: 2px;
  line-height: 1.4;
}
.set-control {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.set-inline {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--text-3);
}
.set-group-title {
  margin: 28px 0 4px;
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.set-head-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}
.set-lead {
  margin: 0;
  color: var(--text-3);
  line-height: 1.5;
  max-width: 520px;
}

.toggle {
  position: relative;
  display: inline-flex;
  cursor: pointer;
  flex-shrink: 0;
}
.toggle input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}
.toggle-track {
  width: 44px;
  height: 24px;
  border-radius: 12px;
  background: var(--line-strong);
  position: relative;
  transition: background 0.15s;
  pointer-events: none;
}
.toggle-thumb {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s, width 0.15s, height 0.15s, top 0.15s, left 0.15s;
}
.toggle input:checked + .toggle-track {
  background: var(--accent);
}
.toggle input:checked + .toggle-track .toggle-thumb {
  transform: translateX(20px);
  background: var(--on-accent);
}
:root[data-theme='dark'] .toggle input:checked + .toggle-track .toggle-thumb {
  background: var(--on-accent);
}
.toggle input:focus-visible + .toggle-track {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.toggle input:disabled {
  cursor: default;
}
.toggle input:disabled + .toggle-track {
  opacity: 0.5;
}

.option-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 0 4px;
}
.option-card {
  width: 148px;
  padding: 16px 12px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
  color: var(--text-2);
  transition: background 0.12s, border-color 0.12s;
}
.option-card .icon {
  font-size: 32px;
}
.option-card:hover {
  background: var(--hover);
}
.option-card.on {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
  background: var(--accent-container);
  color: var(--on-accent-container);
}
.oc-title {
  font-weight: 500;
  font-family: var(--font-ui);
  font-size: 14px;
}
.oc-sub {
  font-size: 12px;
  opacity: 0.8;
}
.select {
  height: 36px;
  min-width: 160px;
  padding: 0 8px;
}
.textarea {
  width: 100%;
  min-height: 110px;
  padding: 10px 12px;
  resize: vertical;
  font-family: var(--font-text);
  line-height: 1.5;
}
.sig-editor {
  padding: 16px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sig-preview {
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
  padding: 12px 16px;
  margin-top: 8px;
  background: var(--surface-read);
}
.sig-preview-title {
  font-size: 12px;
  color: var(--text-3);
  margin-bottom: 8px;
}
.sig-preview-body {
  font-family: var(--font-text);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-2);
  white-space: pre-wrap;
}
.label-table {
  border-top: 1px solid var(--line);
  margin-top: 8px;
}
.label-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  border-bottom: 1px solid var(--line);
  padding: 4px 0;
}
.label-name {
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}
.label-name:hover {
  text-decoration: underline;
}
.label-count {
  color: var(--text-3);
  font-size: 13px;
}
.stat-line {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  padding: 12px 0;
  color: var(--text-3);
  font-size: 13px;
}
.btn.danger-text {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 40%, transparent);
}

/* ---------- dialogs ---------- */
.dialog.wide {
  width: min(720px, 94vw);
}
.field-error {
  color: var(--danger);
  font-size: 12px;
  margin-top: 4px;
  display: block;
}
.label-preview {
  display: flex;
  align-items: center;
  gap: 8px;
