args.command:
cd /tmp && dev-browser --browser sonnet55-mail --headless --timeout 100 <<'EOF'
const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", e => errors.push("pageerror: " + String(e).slice(0, 400)));
const out = {};
// close leftover compose windows
await page.goto("http://127.0.0.1:9232/#/search/has%3Aattachment");
await page.waitForTimeout(700);
out.attRows = await page.evaluate(() => document.querySelectorAll(".row").length);
await page.click(".row >> nth=0");
await page.waitForTimeout(600);
out.cards = await page.evaluate(() => [...document.querySelectorAll(".att-card .att-name")].map(e => e.textContent));
await page.click(".att-open >> nth=0");
await page.waitForTimeout(500);
out.preview = await page.evaluate(() => ({ open: !!document.querySelector(".preview-scrim"), title: document.querySelector(".preview-title")?.textContent, img: !!document.querySelector(".preview-img"), doc: !!document.querySelector(".doc-page") }));
await saveScreenshot(await page.screenshot(), "d-preview.png");
await page.keyboard.press("Escape");
await page.waitForTimeout(300);
out.previewClosed = await page.evaluate(() => !document.querySelector(".preview-scrim"));
// split pane
await page.goto("http://127.0.0.1:9232/#/inbox");
await page.click('[aria-label="Quick settings"]');
await page.click('.qs .segmented [role="radio"]:has-text("Right")');
await page.keyboard.press("Escape");
await page.waitForTimeout(400);
await page.click(".row >> nth=2");
await page.waitForTimeout(700);
out.split = await page.evaluate(() => ({ hash: location.hash, split: !!document.querySelector(".split"), listW: document.querySelector(".list-pane").getBoundingClientRect().width, threadW: document.querySelector(".thread-pane").getBoundingClientRect().width, embedded: !!document.querySelector(".thread-pane.embedded"), rowH: document.querySelector(".row").getBoundingClientRect().height }));
await saveScreenshot(await page.screenshot(), "d-split.png");
console.log(JSON.stringify({ out, errors }, null, 1));
EOF

