          <span key={i} className="kbd-sep">
            {k}
          </span>
        ) : (
          <kbd key={i}>{k}</kbd>
        ),
      )}
    </span>
  );
}

function ShortcutsDialog() {
  return (
    <Modal title="Keyboard shortcuts" onClose={closeDialog} wide>
