cd /tmp && dev-browser --browser sonnet55-mail --headless --timeout 120 <<'EOF'
const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", e => errors.push("pageerror: " + String(e).slice(0, 400)));
page.on("console", m => { if (["error", "warning"].includes(m.type())) errors.push(m.type() + ": " + m.text().slice(0, 300)); });
const out = {};
const routes = ["#/inbox", "#/inbox?tab=promotions", "#/starred", "#/sent", "#/drafts", "#/trash", "#/all", "#/spam", "#/important", "#/snoozed", "#/scheduled", "#/label/work", "#/search/kestrel", "#/search/zzzznothing", "#/settings/general", "#/settings/labels", "#/settings/appearance", "#/settings/signature", "#/settings/data"];
for (const [w, h] of [[320, 640], [390, 844], [820, 1000], [1100, 800], [1440, 900]]) {
  await page.setViewportSize({ width: w, height: h });
  const bad = [];
  for (const r of routes) {
    await page.goto("http://127.0.0.1:9232/" + r);
    await page.waitForTimeout(150);
    const res = await page.evaluate(() => {
      const de = document.documentElement;
      const over = [];
      for (const el of document.querySelectorAll("body *")) {
        const b = el.getBoundingClientRect();
        if (b.width > 0 && b.right > innerWidth + 1 && !el.closest(".sidebar.drawer") && !el.closest(".cat-tabs") && !el.closest(".popover") && !el.closest(".toolbar") && getComputedStyle(el).position !== "fixed") { over.push(el.className.toString().slice(0, 40) + ":" + Math.round(b.right)); if (over.length > 3) break; }
      }
      return { sx: de.scrollWidth > innerWidth, over };
    });
    if (res.sx || res.over.length) bad.push({ r, ...res });
  }
  out[w] = bad;
}
console.log(JSON.stringify({ out, errors }, null, 1));
EOF

