cd /tmp && dev-browser --browser sonnet55-mail --headless --timeout 110 <<'EOF'
const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", e => errors.push("pageerror: " + String(e).slice(0, 400)));
page.on("console", m => { if (["error", "warning"].includes(m.type())) errors.push(m.type() + ": " + m.text().slice(0, 300)); });
const out = {};
await page.goto("http://127.0.0.1:9232/#/inbox");
await page.reload();
await page.waitForTimeout(900);
// close leftover compose windows (discard is destructive; just check count)
out.composeWins = await page.evaluate(() => document.querySelectorAll(".compose-win").length);
const inboxCount = () => page.evaluate(() => document.querySelector(".nav-row.active .nav-count")?.textContent);
out.count0 = await inboxCount();
await page.keyboard.press("j"); await page.keyboard.press("j");
await page.keyboard.press("Enter");
await page.waitForTimeout(600);
out.opened = await page.evaluate(() => location.hash);
await page.keyboard.press("j"); // next (older)
await page.waitForTimeout(500);
out.next = await page.evaluate(() => location.hash);
await page.keyboard.press("k");
await page.waitForTimeout(400);
out.prev = await page.evaluate(() => location.hash);
await page.keyboard.press("#");
await page.waitForTimeout(500);
out.afterDelete = { hash: await page.evaluate(() => location.hash), toast: await page.evaluate(() => document.querySelector(".toast")?.textContent) };
await page.keyboard.press("z");
await page.waitForTimeout(500);
out.afterZ = await page.evaluate(() => [...document.querySelectorAll(".toast")].map(t => t.textContent));
// label shortcut on thread
await page.click(".row >> nth=0");
await page.waitForTimeout(400);
await page.keyboard.press("l");
await page.waitForTimeout(300);
out.labelPicker = await page.evaluate(() => !!document.querySelector(".label-picker"));
await page.keyboard.press("Escape");
await page.keyboard.press("b");
await page.waitForTimeout(300);
out.snoozeDialog = await page.evaluate(() => document.querySelector(".dialog h2")?.textContent);
await page.keyboard.press("Escape");
// search focus /
await page.keyboard.press("u");
await page.keyboard.press("/");
await page.waitForTimeout(200);
out.searchFocus = await page.evaluate(() => document.activeElement?.closest(".searchbar") ? "search" : document.activeElement?.tagName);
console.log(JSON.stringify({ out, errors }, null, 1));
EOF

