args.command:
cd /tmp && dev-browser --browser sonnet55-fresh --headless --timeout 90 <<'EOF'
const page = await browser.getPage("fresh");
const errors = [];
page.on("pageerror", e => errors.push("pageerror: " + String(e).slice(0, 400)));
page.on("console", m => { if (["error", "warning"].includes(m.type())) errors.push(m.type() + ": " + m.text().slice(0, 300)); });
const out = {};
for (const [name, w, h] of [["desktop", 1440, 900], ["mobile", 390, 844]]) {
  await page.setViewportSize({ width: w, height: h });
  await page.goto("http://127.0.0.1:9232/");
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForTimeout(1200);
  out[name] = await page.evaluate(() => ({ title: document.title, h1: document.querySelector("h1")?.textContent, h1Visible: document.querySelector("h1").getBoundingClientRect().width > 0, rows: document.querySelectorAll(".row").length, unread: document.querySelector(".nav-row.active .nav-count")?.textContent, threads: Object.keys(JSON.parse(localStorage.getItem("mail.state.v1") || "{}").threads || {}).length }));
}
await saveScreenshot(await page.screenshot(), "fresh-mobile.png");
console.log(JSON.stringify({ out, errors }, null, 1));
EOF

